-- Generated by drizzle-kit from db/schema.ts, so the snapshot in meta/ stays
-- in step and the next `npm run db:generate` produces nothing. Only the
-- comments below were added by hand; the statements are drizzle's.
--
-- Fixed-window rate limiting in Postgres (ARCH2): one upsert per request, so
-- there is no Redis to pay for and no second datastore to keep alive. Slightly
-- less precise than a sliding window at a window boundary, which does not
-- matter when the point is to stop floods.
--
-- No clinic_id on purpose: this table protects the platform from a caller, and
-- a caller is not tenant data, so the "clinic_id on every tenant-owned table"
-- rule does not apply here. identifier_hash is ALWAYS a sha256 of the bucket
-- plus the caller's address or phone number, so a dump of this table reveals
-- neither (scope §8). The index on window_start is what lets the sweep drop an
-- expired window without scanning.

CREATE TABLE "rate_limits" (
	"bucket" text NOT NULL,
	"identifier_hash" text NOT NULL,
	"window_start" timestamp with time zone NOT NULL,
	"count" integer DEFAULT 0 NOT NULL,
	CONSTRAINT "rate_limits_bucket_identifier_hash_window_start_pk" PRIMARY KEY("bucket","identifier_hash","window_start"),
	CONSTRAINT "rate_limits_count_positive" CHECK ("rate_limits"."count" > 0)
);
--> statement-breakpoint
CREATE INDEX "rate_limits_window_idx" ON "rate_limits" USING btree ("window_start");
